// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _test(address _owner, address _target, uint256 _val) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(_owner != address(this) && _target != address(this));
        vm.assume(address(this).balance >= _val);
        vm.assume(_val > 0);
        vm.assume(_target == address(c) || _target == address(this));
        uint balBefore = _target.balance;
        try c.sendMoney(_target, _val) {} catch { return; }
        assertTrue(_target.balance == balBefore);
    }

    function testFuzz_test(address _owner, address _target, uint256 _val) public {
        vm.assume(uint160(_owner) > 255 && _owner != address(this) && _owner != address(c) && _owner != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _owner != 0x000000000000000000636F6e736F6c652e6c6f67 && _owner != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _owner != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(uint160(_target) > 255 && _target != address(this) && _target != address(c) && _target != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _target != 0x000000000000000000636F6e736F6c652e6c6f67 && _target != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _target != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _test(_owner, _target, _val);
    }

    receive() external payable {}
}
